export type ICapabilityDefinition<
  Context,
  Handle extends ICapabilityHandle = ICapabilityHandle,
> = {
  /** Unique, nonblank registration name; spelling is retained rather than trimmed. */ readonly name: string;
  /** * Activates this capability. * * Async activation supports loading enhancements such as persistence on demand. Dynamic imports * keep the disabled capability's chunk out of the initial bundle. Receives the host's original * context reference and must return a handle with a callable dispose method. A rejected start or * invalid handle becomes a failed enable result; a late valid handle is released, not adopted. */ activate(
    context: Context,
  ): Handle | Promise<Handle>;
};

export type ICapabilityEnableResult =
  | /** A current handle is available through the host. */ {
      readonly status: typeof CapabilityEnableStatus.enabled;
    } /** The flag denies activation, including a pending activation revoked by that flag. */
  | {
      readonly status: typeof CapabilityEnableStatus.gated;
    } /** Disable, disposal, or a newer generation superseded this activation. */
  | {
      readonly status: typeof CapabilityEnableStatus.cancelled;
    } /** Activation or handle admission failed; error retains the original failure. */
  | { readonly status: typeof CapabilityEnableStatus.failed; readonly error: unknown };

export type ICapabilityHandle = {
  /** Releases this activation; the host captures this method once and waits for returned cleanup. */ dispose(): void | PromiseLike<void>;
};

