})
const host = createCapabilityHost(undefined, { flags: { export: true } })
host.register({ name: 'export', activate: () => pending })
const enabling = host.enable('export')
host.setFlag('export', false)
finish({
  dispose: () => {
    console.log('释放晚到句柄')
  }
})
console.log('启用结果:', (await enabling).status)
