export type ICapabilityHost<Context> = {
  /** * Captures a name and activation function without activating. Duplicate names, malformed recipes, * disposed hosts, and synchronous lifecycle reentry fail with the corresponding host code. */ register<
    Handle extends ICapabilityHandle,
  >(
    definition: ICapabilityDefinition<Context, Handle>,
  ): void;
  /** Fresh registration-order name array; it is a snapshot, not the mutable registry. */ readonly names: readonly string[];
  /** Reads current lifecycle state; an unknown name throws NOT_REGISTERED, even after disposal. */ state(
    name: string,
  ): ICapabilityState;
  /** Returns the enabled handle or undefined; unknown names throw NOT_REGISTERED. */ handle<
    Handle extends ICapabilityHandle,
  >(
    name: string,
  ): Handle | undefined;
  /** * Returns the retained activation or release failure, or undefined. Starting a new attempt or * deactivating clears the prior diagnostic; unknown names throw NOT_REGISTERED. */ error(
    name: string,
  ): unknown;
  /** * Updates one flag. Disabling synchronously invalidates pending activation and releases the * handle. Enabling does not activate. A name may be configured before it is registered; the * setter does not wait for asynchronous cleanup. */ setFlag(
    name: string,
    enabled: boolean,
  ): void;
  /** * Atomically replaces all flags. Missing capabilities are denied, so removed keys cannot retain * an earlier true value. An unreadable snapshot gates every entry before INVALID_OPTION is * thrown. Accessor flags are not evaluated, and this setter does not await cleanup. */ setFlags(
    flags: Readonly<Record<string, boolean>>,
  ): void;
  /** * Activates the capability and returns its structured activation outcome. * * Concurrent in-flight calls share the exact Promise and one activation. A denied flag resolves * gated without activation; an already enabled entry resolves enabled. Activation failures * resolve failed, while unknown names, disposed hosts, and transition reentry reject. */ enable(
    name: string,
  ): Promise<ICapabilityEnableResult>;
  /** * Synchronously invalidates activation and releases the current handle, then waits for this * entry's in-flight activation and cleanup, including late results. Resolves true only if the * entry was on; pending activation cancellation returns false. Cleanup failures are reported. */ disable(
    name: string,
  ): Promise<boolean>;
  /** * Makes the host terminal and releases handles in reverse activation-completion order, then waits * for every in-flight activation and release. Cleanup failures are reported without stopping * other releases. Later calls fail with HOST_TRANSITIONING until the first completion Promise * settles; after completion they return that original Promise by identity. */ dispose(): Promise<void>;
  /** Becomes true synchronously when final disposal begins, before pending cleanup settles. */ readonly disposed: boolean;
};

export type ICapabilityHostOptions = {
  /** * Initial flag snapshot. The gate denies activation by default. Only own data properties whose * value is exactly `true` permit activation. * * The host copies this snapshot. Use `setFlag()` or `setFlags()` for later changes. Mutating the * input object cannot bypass the state machine. `setFlag(name, false)` atomically invalidates * pending activation and releases the current handle. A separate `disable()` call is * unnecessary. */ readonly flags?: Readonly<
    Record<string, boolean>
  >;
  /** * Reports activation or release failures; omitted by default. Reporter failures preserve gate * state and error(name) diagnostics and reach the shared terminal reporting channel. */ readonly onError?: (
    name: string,
    error: unknown,
  ) => void;
};

export declare function createCapabilityGraph(
  options?: ICapabilityGraphOptions,
): ICapabilityGraph;

examples:
import { createCapabilityGraph, type IGraphNodeId } from '@migaia/capability/graph'

const config = 'config' as IGraphNodeId
const screen = 'screen' as IGraphNodeId
const graph = createCapabilityGraph()
graph.register({
  id: screen,
  kind: 'view',
  dependencies: [{ provider: config, required: true }],
  start: (context) => {
    console.log('启动页面:', context.get<{ theme: string }>(config).theme)
    return {
      value: 'screen',
      release: () => {
        console.log('释放页面')
      }
    }
  }
})
graph.register({
  id: config,
  kind: 'service',
  dependencies: [],
  start: () => {
    console.log('启动配置')
    return {
      value: { theme: 'dark' },
      release: () => {
        console.log('释放配置')
      }
    }
  }
})
await graph.ready()
console.log('状态:', graph.state)
await graph.dispose()

import { createCapabilityGraph, type IGraphNodeId } from '@migaia/capability/graph'

const provider = 'config' as IGraphNodeId
const consumer = 'screen' as IGraphNodeId
const primary = new Error('页面启动失败')
const graph = createCapabilityGraph()
graph.register({
  id: provider,
  kind: 'service',
  dependencies: [],
  start: () => ({
    value: { theme: 'dark' },
    release: () => {
      console.log('回滚配置')
    }
  })
})
graph.register({
  id: consumer,
  kind: 'view',
  dependencies: [{ provider, required: true }],
  start: () => {
    throw primary
  }
})
try {
  await graph.ready()
} catch (error) {
  console.log('保留原错:', error === primary)
  console.log('错误码:', (error as Error & { code: string }).code)
}
console.log('提供方:', graph.nodeState(provider).state)
console.log('图状态:', graph.state)
await graph.dispose()

