export type ICapabilityGraph = {
  /** Captures a node while open; malformed, duplicate, or post-ready registration throws. */ register<
    T,
  >(
    node: IGraphNodeDefinition<T>,
  ): void;
  /** * Freezes registration and starts provider levels in order, with same-level starts concurrent. * Shares one Promise; failure rolls back acquired resources without implicit retry. */ ready(): Promise<void>;
  /** * Returns a frozen diagnostic record, retaining payload identity; unknown IDs throw * GRAPH_UNKNOWN_NODE. */ nodeState(
    id: IGraphNodeId,
  ): IGraphNodeDiagnostic;
  /** * Read the same value projection as nodeState without allocating a diagnostic. Existing nodes * return undefined until the whole graph is ready and after disposal; undefined is valid data. An * unknown id retains GRAPH_UNKNOWN_NODE. Payload identity and mutability stay caller-owned. */ readValue<
    T = unknown,
  >(
    id: IGraphNodeId,
  ): T | undefined;
  /** Frozen registration-order ID snapshot; retained for diagnostics after disposal. */ readonly nodes: readonly IGraphNodeId[];
  /** Whole-graph admission/startup/cleanup phase, independent of per-node state. */ readonly state: ICapabilityGraphState;
  /** Retained graph startup or disposal failure, otherwise undefined. */ readonly error:
    | unknown
    | undefined;
  /** * Closes admission and value visibility immediately, then releases in reverse topology order. * Shares one Promise, including while pending. Release failures reject with traceable graph * errors, retaining existing graph-owned codes. A non-cooperative start can finish later and its * result is still released. */ dispose(): Promise<void>;
  /** * Reads a declared ready direct provider for a registered consumer. Startup or quiescence rejects * admission; terminal graphs and unavailable or undeclared providers throw graph errors. */ get<
    T = unknown,
  >(
    consumer: IGraphNodeId,
    provider: IGraphNodeId,
  ): T;
};

export type ICapabilityGraphOptions = {
  /** * Optional secondary diagnostic sink, captured once; reporter failure does not replace graph * results. */ readonly onError?: (
    error: unknown,
  ) => void;
};

export type IGraphDependency = {
  /** Registered provider ID whose startup must finish before this consumer starts. */ readonly provider: IGraphNodeId;
  /** Must be true; optional edges belong to the dynamic graph entry. */ readonly required: true;
};

export type IGraphNodeDefinition<T> = {
  /** Unique nonempty ID, captured at registration. */ readonly id: IGraphNodeId;
  /** Nonempty application classification used in diagnostics, not dependency routing. */ readonly kind: string;
  /** Required direct-provider edges, snapshotted before startup and checked for duplicates. */ readonly dependencies: readonly IGraphDependency[];
  /** * Creates one primary instance after providers are ready. Throws and rejections fail startup and * roll back acquired resources; a result arriving after disposal is released, not exposed. */ readonly start: (
    context: IGraphStartContext,
  ) => IGraphNodeInstance<T> | PromiseLike<IGraphNodeInstance<T>>;
};

export type IGraphNodeDiagnostic = {
  /** Registered node identity. */ readonly id: IGraphNodeId;
  /** Captured application classification. */ readonly kind: string;
  /** Resource lifecycle state; distinct from the whole graph's state. */ readonly state: ICapabilityGraphNodeState;
  /** Payload projection; static graphs expose it only while the whole graph is ready. */ readonly value: unknown;
  /** Retained node failure, or undefined when no failure is recorded. */ readonly error: unknown;
  /** Cause for a blocked node when dependency availability is responsible. */ readonly reason?: GraphBlockedReason;
  /** Optional composition binding retained by the dynamic owner. */ readonly binding?: unknown;
  /** Monotonic lifecycle generation for this node. */ readonly generation?: number;
  /** Stable registration ordinal retained across same-edge replacement. */ readonly ordinal?: number;
  /** Deterministic schedule rank retained when topology edges do not change. */ readonly rank?: number;
  /** Dependency depth retained when topology edges do not change. */ readonly level?: number;
};

