export type IGraphNodeInstance<T> = {
  /** Published payload; its identity and mutability remain owned by the application. */ readonly value: T;
  /** Releases the primary resource after dependents; failures remain observable during disposal. */ readonly release: (
    context: IGraphReleaseContext,
  ) => void | PromiseLike<void>;
};

export type IGraphReleaseContext = {
  /** Lifecycle-owned release signal; cleanup should cooperate with its cancellation state. */ readonly signal: IAbortSignal;
  /** Identity of the resource being released. */ readonly nodeId: IGraphNodeId;
  /** Sends secondary cleanup diagnostics without replacing the primary graph outcome. */ readonly report: (
    error: unknown,
  ) => void;
};

export type IGraphStartContext = {
  /** Identity of the node whose start is currently running. */ readonly nodeId: IGraphNodeId;
  /** Graph-generation signal, cancelled by disposal; startup must cooperate to stop work. */ readonly signal: INativeAbortSignal;
  /** Reads a ready, declared direct provider while this start remains active; otherwise throws. */ readonly get: <
    T = unknown,
  >(
    provider: IGraphNodeId,
  ) => T;
  /** * Provisionally owns an auxiliary resource, returning it unchanged. Startup failure rolls it * back; success transfers it to graph cleanup after the primary instance. The primary value must * not be the same resource. Invalid descriptors fail with GRAPH_INVALID_OPTION. */ readonly own: <
    T,
  >(
    resource: T,
    descriptor: IReleaseDescriptor,
  ) => T;
};

