    node: IDynamicGraphNodeDefinition<T>,
    binding?: TBinding,
    options?: IGraphReplaceOptions<TBinding>,
  ): Promise<IGraphMutationResult>;
  /** * Queues startup of currently satisfiable nodes and sets container ready; blocked nodes may * remain. */ ready(): Promise<void>;
  /** * Returns a fresh, unfrozen diagnostic projection with original value/binding references; unknown * IDs throw. */ nodeState(
    id: IGraphNodeId,
  ): IGraphNodeDiagnostic;
  /** * Reads a binding without checking node availability or acquiring a lease; absent IDs return * undefined. */ getBinding<
    T = TBinding,
  >(
    id: IGraphNodeId,
  ): T | undefined;
  /** * Returns a frozen lease for a ready non-undefined binding; unavailable or sealed generations * reject. */ acquireBinding(
    id: IGraphNodeId,
  ): IGraphBindingLease<TBinding>;
  /** * Immediately closes admission, then queues final cleanup behind accepted work without an * admission timeout. Repeated calls share the exact Promise. Definitions are cleared and state * becomes terminal even if releaseBatch rejects; the composition owner must honor lease fences. */ dispose(): Promise<void>;
