export type IGenerationController = {
  readonly generation: number;
  readonly disposed: boolean;
  /** * Starts a new generation, superseding whatever was active. Optionally auto-aborts after * `timeoutMs`. */ begin(options?: {
    readonly timeoutMs?: number;
  }): IGenerationRequest;
  isCurrent(token: IGenerationToken): boolean;
  /** * Releases the matching current token's timer and parent subscription without aborting its * signal. Returns false for stale/disposed tokens; cleanup failures retain cancellation codes and * causes after invalidating the token. */ complete(
    token: IGenerationToken,
  ): boolean;
  /** * Invalidates the current generation without disposing the controller — a later `begin()` still * works. */ supersede(
    reason?: unknown,
  ): void;
  /** * Adopts `value` under `token`'s generation. Returns `true` and keeps `value` with the caller if * that generation is still current. Otherwise releases `value` via `release` and returns `false` * — a release failure is funneled to `onReleaseError` (or the controller `report` when omitted) * and never mutates controller state, so it cannot poison whichever generation is current now. */ adopt<
    T,
  >(
    token: IGenerationToken,
    value: T,
    release: (value: T) => void | PromiseLike<void>,
    onReleaseError?: (error: unknown) => void,
  ): boolean;
