  /** Closing/closed admission rejects new calls, first stream next or resize; create another pool. */ readonly poolClosed: 'POOL_CLOSED';
  /** * All available slots are reserved and the bounded FIFO is full; the new call never reaches a * Peer. */ readonly queueFull: 'QUEUE_FULL';
  /** * Queued cancellation removes only its FIFO entry; a native AbortError retains the signal reason * on cause. */ readonly callAborted: 'CALL_ABORTED';
  /** * Final close attempted all members but retained one or more close failures, including earlier * retirement failures. Inspect AggregateError.errors/cause; the pool is terminal, not reopened. */ readonly closeFailed: 'CLOSE_FAILED';
};

export declare const RpcProcessErrorCode: {
  /** Native PID sampling failed; report its cause and display unavailable without retrying. */ readonly usageSampleFailed: 'PROCESS_USAGE_SAMPLE_FAILED';
  /** Host options are invalid before launch; callers must correct the named field. */ readonly hostInvalidOption: 'PROCESS_HOST_INVALID_OPTION';
  /** Facade release has begun; callers must create a new facade instead of enqueueing work. */ readonly hostClosed: 'PROCESS_HOST_CLOSED';
  /** Handshake exceeded its scheduler deadline; caller must open a new channel. */ readonly handshakeTimeout: 'PROCESS_HANDSHAKE_TIMEOUT';
  /** Peer authorization failed; caller must not retry without valid credentials. */ readonly authRejected: 'PROCESS_CHANNEL_AUTH_REJECTED';
  /** * A closed channel rejected work or its close observer/resource cleanup failed; inspect * cause/errors. */ readonly channelClosed: 'PROCESS_CHANNEL_CLOSED';
  /** Dial or launch could not establish a channel; caller may inspect the original cause. */ readonly connectFailed: 'PROCESS_CHANNEL_CONNECT_FAILED';
  /** The requested local listener could not bind; caller must choose an available address. */ readonly listenFailed: 'PROCESS_CHANNEL_LISTEN_FAILED';
  /** Invalid process-plugin options are rejected before launch; caller must correct the named field. */ readonly pluginInvalidOption: 'PROCESS_PLUGIN_INVALID_OPTION';
  /** * Invalid resilience limits, ownership, or health configuration; correct the named field before * opening a connection. */ readonly resilienceInvalidOption: 'PROCESS_RESILIENCE_INVALID_OPTION';
  /** A connection, call-rate, or payload limit rejected admission before provider execution. */ readonly connectionLimit: 'PROCESS_CONNECTION_LIMIT';
  /** * A shared target is suspended after an explicit instance-health event until a ready replacement * exists. */ readonly instanceUnhealthy: 'PROCESS_INSTANCE_UNHEALTHY';
  /** * An enabled native health ping returned false before its supervision deadline; the owner must * restart the unit. */ readonly healthPingFailed: 'PROCESS_HEALTH_PING_FAILED';
  /** A terminal registration rejects new remote calls before they reach its inactive generation. */ readonly terminalCall: 'PROCESS_TERMINAL_CALL';
  /** A liquidated registration cannot restart; the caller must create a new registration. */ readonly liquidated: 'PROCESS_LIQUIDATED';
};

export declare const RpcRemoteLayerErrorCode: {
  /** A passive watch exceeded 100 unread events; query current state before subscribing again. */ readonly runtimeEventOverflow: 'RUNTIME_EVENT_OVERFLOW';
  /** A description or control payload violates the remote contract; correct it before retrying. */ readonly contractInvalid: 'REMOTE_CONTRACT_INVALID';
  /** * HostUnUse, including dryRun, lacks this connection's live adoption of the same remotely * installed definition. Complete hostUse before removing it. */ readonly hostNotAdopted: 'REMOTE_HOST_NOT_ADOPTED';
  /** A supervisor cannot provide a ready unit or a channel cannot open; inspect the cause. */ readonly startFailed: 'REMOTE_START_FAILED';
  /** The registration was released or its generation left; wait for another ready generation. */ readonly closed: 'REMOTE_CLOSED';
  /** * A sent request lost its result with the generation; reconcile before another non-idempotent * call. */ readonly resultUnknown: 'REMOTE_RESULT_UNKNOWN';
};

export declare const RpcThreadErrorCode: {
  /** Native Worker sampling failed; retain its cause and display unavailable. */ readonly usageSampleFailed: 'THREAD_USAGE_SAMPLE_FAILED';
};

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://migaia.dev/rpc/protocol.schema.json",
  "title": "migaia.rpc/2 semantic protocol",
  "$comment": "Self-contained JSON projection of rpc-contract ./protocol. Native binary/carrier extension shells are separate boundaries. Preserve object own-key order during encode/decode; schema does not sort data. JSON Schema checks representable structural constraints only; authoritative pure validators enforce all semantic admission. Fixed protocol records ignore unknown fields (core ); portable byte tags and method-schema definitions retain their own admission rules.",
  "oneOf": [
    {
      "$ref": "#/$defs/hello"
