    },
    {
      "$ref": "#/$defs/group"
    },
    {
      "$ref": "#/$defs/result"
    },
    {
      "$ref": "#/$defs/error"
    },
    {
      "$ref": "#/$defs/cancel"
    },
    {
      "$ref": "#/$defs/stream"
    },
    {
      "$ref": "#/$defs/outcomeFrame"
    },
    {
      "$ref": "#/$defs/control"
    },
    {
      "$ref": "#/$defs/directoryFrame"
    }
  ],
  "$defs": {
    "identifier": {
      "type": "string",
