        "value": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "providerId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128
        }
      }
    },
    "route": {
      "type": "object",
      "required": [
        "applicationVersion",
        "senderId",
        "targetId",
        "receiverId",
        "sentAt"
      ],
      "properties": {
        "applicationVersion": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128
