          "type": "object",
          "required": [
            "profile",
            "kind",
            "id",
            "route",
            "task",
            "operation",
            "state",
            "store",
            "outcome"
          ],
          "properties": {
            "profile": {
              "const": "migaia.rpc/2"
            },
            "kind": {
              "const": "outcome"
            },
            "id": {
              "$ref": "#/$defs/identifier"
            },
            "route": {
              "$ref": "#/$defs/route"
            },
            "task": {
              "allOf": [
                {
                  "$ref": "#/$defs/task"
                },
                {
                  "properties": {
                    "mode": {
                      "enum": [
                        "outcome"
                      ]
                    }
                  }
                }
              ]
            },
            "operation": {
              "const": "result"
            },
            "state": {
              "const": "done"
            },
            "store": {
              "$ref": "#/$defs/store"
            },
            "outcome": {
              "$ref": "#/$defs/outcome"
            },
            "extensions": {
              "$ref": "#/$defs/extensions"
            }
          }
        }
      ]
    },
    "control": {
      "type": "object",
      "required": [
        "profile",
        "kind",
        "id",
        "route",
        "operation"
      ],
      "properties": {
        "profile": {
          "const": "migaia.rpc/2"
        },
        "kind": {
          "const": "control"
        },
        "id": {
          "$ref": "#/$defs/identifier"
        },
        "route": {
          "$ref": "#/$defs/route"
        },
        "operation": {
          "enum": [
            "ping",
            "pong",
            "drain",
            "close"
          ]
        },
        "reason": {
          "$ref": "#/$defs/errorGraph"
        }
      }
    },
    "directoryFrame": {
      "type": "object",
      "required": [
        "profile",
        "kind",
        "id",
        "route",
        "directory"
      ],
      "properties": {
        "profile": {
          "const": "migaia.rpc/2"
        },
        "kind": {
          "const": "directory"
        },
        "id": {
          "$ref": "#/$defs/identifier"
        },
        "route": {
          "$ref": "#/$defs/route"
        },
        "directory": {
          "$ref": "#/$defs/directory"
        }
      }
    }
  },
  "x-migaia-owner-validation": {
    "pureEntry": "@migaia/rpc-contract/protocol normalizeRpcFrame",
    "errorGraph": "normalizeRpcWireError validates index domain against nodes.length, scalar Unicode/UTF-8 limits and total error/data byte budget; cycles and repeated references are legal.",
    "handshake": "normalizeRpcHandshake checks unique version majors, required-handler subset and peer/directory identity; acceptRpcHandshake/completeRpcHandshake validate actual bilateral offers.",
    "directory": "normalizeRpcDirectory checks unique method names, supported method-schema references and portable budgets.",
    "group": "normalizeRpcGroupResult checks first-failure and not-executed suffix ordering.",
    "portable": "Pure portable admission rejects cycles, nonfinite numbers, unsupported values, invalid bytes tags and excessive depth; native backings/sidecars and transfer authority are outside JSON data.",
    "budgetAndState": "Schema cannot establish encoded frame bytes, UTF-8 totals, code-unit identifier length, deadline reduction across hops, live call correlation, stream credit/state or runtime IO. Session, codec and work owners enforce these."
  }
}

