              },
              "input": {
                "$ref": "#/$defs/methodSchema"
              },
              "output": {
                "$ref": "#/$defs/methodSchema"
              },
              "yield": {
                "$ref": "#/$defs/methodSchema"
              }
            }
          }
        },
        "nodeId": {
          "type": "string",
          "pattern": "^[0-9a-f]{32}$"
        }
      },
      "$comment": "Method names must be unique; local method-schema references and semantic budgets are checked by the pure directory validator."
    },
    "nodeIndex": {
      "type": "integer",
      "minimum": 0,
      "maximum": 1023
    },
    "errorNode": {
      "type": "object",
      "required": [
        "source",
        "code",
        "name",
        "message",
        "stack"
      ],
      "properties": {
        "source": {
          "type": "string",
          "minLength": 1
        },
        "code": {
          "type": "string",
          "minLength": 1
        },
        "name": {
          "type": "string",
          "minLength": 1
        },
        "message": {
          "type": "string"
        },
        "stack": {
          "type": "string",
          "minLength": 1
        },
        "cause": {
          "$ref": "#/$defs/nodeIndex"
        },
        "errors": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/nodeIndex"
          }
        },
        "data": {
          "$ref": "#/$defs/portable"
        },
        "route": {
          "type": "array",
          "minItems": 1,
          "maxItems": 17,
          "items": {
            "type": "string",
            "pattern": "^[0-9a-f]{32}$"
          }
        },
        "truncated": {
          "const": true
        }
      }
    },
    "errorGraph": {
      "type": "object",
      "required": [
        "root",
        "nodes"
      ],
      "properties": {
        "root": {
          "$ref": "#/$defs/nodeIndex"
        },
        "nodes": {
          "type": "array",
          "minItems": 1,
          "maxItems": 1024,
          "items": {
            "$ref": "#/$defs/errorNode"
