      "properties": {
        "mode": {
          "enum": [
            "request",
            "notify",
            "stream",
            "group",
            "outcome"
          ]
        },
        "callerId": {
          "$ref": "#/$defs/identifier"
        },
        "callerGeneration": {
          "$ref": "#/$defs/generation"
        },
        "targetGeneration": {
          "$ref": "#/$defs/generation"
        }
      },
      "if": {
        "properties": {
          "mode": {
            "enum": [
              "request",
              "notify",
              "stream"
            ]
          }
        }
      },
      "then": {
        "required": [
          "method"
        ],
        "properties": {
          "method": {
            "$ref": "#/$defs/identifier"
          }
        }
      }
    },
    "options": {
      "type": "object",
      "required": [],
      "properties": {
