        "idempotencyKey": {
          "type": "string",
          "pattern": "^[A-Za-z0-9._:~-]{1,128}$"
        }
      }
    },
    "step": {
      "type": "object",
      "required": [
        "method"
      ],
      "properties": {
        "method": {
          "$ref": "#/$defs/identifier"
        },
        "payload": {
          "$ref": "#/$defs/portable"
        }
      }
    },
    "groupResult": {
      "type": "array",
      "minItems": 1,
