          }
        },
        {
          "type": "object",
          "required": [
            "event",
            "seq",
            "value"
          ],
          "properties": {
            "event": {
              "const": "item"
            },
            "seq": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "value": {
              "$ref": "#/$defs/portable"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "event",
            "seq"
          ],
          "properties": {
            "event": {
              "const": "end"
            },
            "seq": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "value": {
              "$ref": "#/$defs/portable"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "event",
            "seq",
            "error"
          ],
          "properties": {
            "event": {
              "const": "fail"
            },
            "seq": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "error": {
              "$ref": "#/$defs/errorGraph"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "event",
            "seq"
          ],
          "properties": {
            "event": {
              "const": "cancelled"
            },
            "seq": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "error": {
              "$ref": "#/$defs/errorGraph"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "event",
            "seq"
          ],
          "properties": {
            "event": {
              "const": "finish-without-items"
            },
            "seq": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "reason": {
              "$ref": "#/$defs/errorGraph"
            }
          }
        }
      ],
      "$comment": "Sequence progression, credits, terminal state and max item byte budget are checked by pure stream helpers and StreamChannel, not by this event shape alone."
    },
    "store": {
      "oneOf": [
        {
          "type": "object",
          "required": [
            "kind",
            "epoch",
            "continuity"
          ],
          "properties": {
            "kind": {
              "enum": [
                "memory",
                "external"
              ]
            },
            "epoch": {
              "type": "string",
              "minLength": 1
            },
            "continuity": {
              "enum": [
                "retained",
                "lost-since-restart"
              ]
            }
          }
        },
        {
          "type": "object",
          "required": [
            "kind",
            "continuity"
          ],
          "properties": {
            "kind": {
              "const": "unavailable"
            },
            "continuity": {
              "const": "unavailable"
            }
          }
        }
      ]
    },
    "outcome": {
      "allOf": [
        {
          "if": {
            "properties": {
              "mode": {
                "const": "stream"
              }
            }
          },
          "else": {
            "properties": {
              "completion": {
                "not": {
                  "required": [
                    "streamTerminal"
                  ]
                }
              }
            }
          }
        }
      ],
      "oneOf": [
        {
          "type": "object",
          "required": [
            "mode",
            "targetGeneration",
            "completion"
          ],
          "properties": {
            "mode": {
