    T,
  >(
    definition: IAtomDefinition<T>,
  ): T;
  /** React/concurrent speculative read; value may be discarded after the turn. */ preview<
    T,
  >(
    definition: IAtomDefinition<T>,
  ): T;
  /** * Writes a source definition with a new value or an updater of the previous value. Listed before * the general overload so the updater's `previous` parameter is typed from the definition. */ set<
    T,
  >(
    definition: IPrimitiveDefinition<T> | IPrimitiveFactoryDefinition<T>,
    update: IAtomUpdate<T>,
  ): void;
  /** Writes any writable definition; a writable derived one returns its `write` result. */ set<
    T,
    Args extends readonly unknown[],
    Result,
  >(
    definition: IWritableAtomDefinition<T, Args, Result>,
    ...args: Args
  ): Result;
  /** * Writes source definitions within one batch and one untracked operation; subscribers are * notified once after the batch. The call first resolves every entry and runs every updater in * input order, then writes. An entry that resolves to a non-source definition (OVERRIDE_CONTRACT) * or an updater that throws leaves every atom unchanged. A repeated definition's updater receives * the value from its previous entry; updaters reading other atoms see the values from before the * call. * * Each entry keeps its own value type: `Ts` is inferred from the definitions only, so entries of * different types can share one call and each updater is checked against its own definition. */ setMany<
    Ts extends readonly unknown[],
  >(entries: {
    readonly [K in keyof Ts]: readonly [
      IPrimitiveDefinition<Ts[K]> | IPrimitiveFactoryDefinition<Ts[K]>,
      IAtomUpdate<NoInfer<Ts[K]>>,
    ];
  }): void;
  /** * Subscribes to a definition and returns an unsubscribe function. * * Adapters subscribe through this boundary instead of accessing graph nodes, leaving * instantiation strategies independent. */ sub<
    T,
  >(
    definition: IAtomDefinition<T>,
    onChange: () => void,
  ): IDisposer;
  /** Routes a read-only derived definition to any definition with the same value type. */ override<
    T,
  >(
    definition: IDerivedDefinition<T>,
    replacement: IAtomDefinition<NoInfer<T>>,
