// 内部组合类型，不是公开导出；使用者导入 ICollector 或 IFieldCollector。
type ICollectorActions<T, Self> = {
  readonly result: readonly T[]
  fieldBy<const P extends readonly [IObjectPathInput<T>, ...IObjectPathInput<T>[]]>(
    ...paths: P
  ): IFieldCollector<T, P[number]>
