  readonly failedAt: number;
  readonly failedKey: IObjectPathSegment;
  readonly resolvedPath: IObjectPathTuple;
  readonly parent: unknown;
};

export type IPathProbe<T, P extends IObjectPathInput<T>> =
  | IPathValueProbe<T, P>
  | IPathMissingProbe<P>
