symbols.signature:
export class ConversionResult {
  private constructor();
  /** * Releases the WASM metadata after reading this result, including failed results. * Call once; do not read properties or reuse this wrapper after disposal. * Input and output arena allocations remain live until `dealloc_bytes(id)`. */ free(): void;
  /** * Releases this result's metadata when leaving an explicit resource-management scope. * This is the same operation as `free()`; use one disposal path per result. * Input and output arena allocations require separate `dealloc_bytes(id)` calls. */ [Symbol.dispose](): void;
  /** * Returns an empty string on success or the current operation's failure reason. * * Invalid handles and lengths report `unknown allocation id or length past * capacity`. Initial output allocation failure reports `arena exhausted`. * Parse and write failures start with `json to msgpack failed:` or * `msgpack to json failed:`. * Read before freeing this metadata wrapper; no global error lookup is needed. */ readonly error: string;
  /** * Returns the new output allocation id, or `0` when conversion failed. * * A nonzero id belongs to the caller and remains live after this result's * `free()`. Read the exact output range with `len` and release the allocation * with `dealloc_bytes(id)` when finished. The input id is never consumed. */ readonly id: number;
  /** * Returns the exact number of output bytes, or `0` on failure. * * Use this length when reading output or passing it to another converter. * `byte_len_of(id)` includes arena padding and can exceed this value. */ readonly len: number;
}

