symbols.signature:
export type InitInput =
  | RequestInfo
  | URL
  | Response
  | BufferSource
  | WebAssembly.Module;

export interface InitOutput {
  /** Linear memory for arena views. Read its current buffer again after allocation or conversion can grow memory. */ readonly memory: WebAssembly.Memory;
  /** Generated metadata destructor: a is a result pointer; b selects explicit disposal (0) or finalization (1). Use ConversionResult.free() instead of calling this directly. */ readonly __wbg_conversionresult_free: (
    a: number,
    b: number,
  ) => void;
  /** Raw allocation entry: a is the requested byte count. Returns a live arena id or 0 on allocation failure; prefer the named alloc_bytes wrapper. */ readonly alloc_bytes: (
    a: number,
  ) => number;
  /** Raw capacity entry: a is an arena id. Returns its rounded byte capacity, or 0 for an unknown id or a live zero-byte block. */ readonly byte_len_of: (
    a: number,
  ) => number;
  /** Raw error getter: a is a live metadata pointer. Returns an allocated UTF-8 pointer/length pair; the ConversionResult.error getter decodes and releases that temporary storage. */ readonly conversionresult_error: (
    a: number,
  ) => [number, number];
  /** Raw output-id getter: a is a live metadata pointer. Returns the output arena id, or 0 for a failed conversion; prefer ConversionResult.id. */ readonly conversionresult_id: (
    a: number,
  ) => number;
  /** Raw output-length getter: a is a live metadata pointer. Returns the exact output byte count, or 0 for failure; prefer ConversionResult.len. */ readonly conversionresult_len: (
    a: number,
  ) => number;
  /** Raw arena release: a is an allocation id. Returns 1 when a live block was released, otherwise 0; the named wrapper exposes a boolean. */ readonly dealloc_bytes: (
    a: number,
  ) => number;
  /** Raw JSON conversion: a is the input arena id and b its exact byte count. Returns a metadata pointer, not a ConversionResult object; use the named JavaScript wrapper. */ readonly json_to_msgpack: (
    a: number,
    b: number,
  ) => number;
  /** Raw MessagePack conversion: a is the input arena id and b its exact byte count. Returns a metadata pointer, not a ConversionResult object; use the named JavaScript wrapper. */ readonly msgpack_to_json: (
    a: number,
    b: number,
  ) => number;
  /** Raw pointer entry: a is an arena id. Returns its eight-byte-aligned memory offset, or 0 for an unknown id. */ readonly ptr_of: (
    a: number,
  ) => number;
  /** Generated table holding JavaScript references required by wasm-bindgen. Owned and initialized by the glue; application arena data does not belong here. */ readonly __wbindgen_externrefs: WebAssembly.Table;
  /** Generated temporary-storage release: a is a pointer, b its byte length, and c its alignment. Owned by the glue; arena ids must use dealloc_bytes instead. */ readonly __wbindgen_free: (
    a: number,
    b: number,
    c: number,
  ) => void;
  /** Generated startup hook called by module initialization. Applications must initialize through init or initSync rather than invoking this hook again. */ readonly __wbindgen_start: () => void;
}

